const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

// Initialize Scalekit instance using environment variables
const scalekit = new Scalekit({
  environmentId: process.env.SCALEKIT_ENVIRONMENT_ID || 'your_environment_id',
  apiKey: process.env.SCALEKIT_API_KEY || 'your_api_key'
});

// Generate authorization URL with specified parameters
const authorizationUrl = scalekit.getAuthorizationUrl({
  redirect_uri: 'http://localhost:3001/callback',
  organization_id: 'org_1234567890',
  state: 'random_state_string'
});

// Write the URL to output.log
const outputPath = path.join(__dirname, 'output.log');
fs.writeFileSync(outputPath, authorizationUrl);

console.log('Authorization URL generated successfully:');
console.log(authorizationUrl);
console.log(`\nURL written to: ${outputPath}`);

